    before = naive.replace(tzinfo=tz, fold=0).utcoffset()
    after = naive.replace(tzinfo=tz, fold=1).utcoffset()
    lo = (naive - after).replace(tzinfo=UTC)
    hi = (naive - before).replace(tzinfo=UTC)
    # find first minute where offset == after
    while lo < hi:
