        mid = mid.replace(second=0, microsecond=0)
        if mid <= lo: mid = lo + dt.timedelta(minutes=1)
        if mid.astimezone(tz).utcoffset() == after:
            hi = mid
        else:
            lo = mid + dt.timedelta(minutes=1) if mid < hi else hi
            if lo >= hi: break
    return hi

